func:
if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: { valid: true, latency_ms: Date.now() - (msg.payload.timestamp * 1000) }
};

node.status({ fill: 'green', shape: 'dot', text: `${msg.payload.device_id} (${count})` });
return msg;

msg.payload = { ...msg.enriched, category: 'PLC', priority: 'high' };
msg.topic = 'collector/ingest';
return msg;

msg.payload = { ...msg.enriched, category: 'Sensor', priority: 'medium' };
msg.topic = 'collector/ingest';
return msg;

if (msg.payload.type !== 'register') return null;
let addr = msg.payload.address;
let val = msg.payload.value;
let dev = addr === 0 ? 'Conveyor1' : addr === 1 ? 'Conveyor2' : addr === 2 ? 'Placer1' : null;
if (!dev) return null;
return { topic: `factory/command/${dev}`, payload: { rpm: val, is_on: val > 0 } };

// THE BRAIN - Routes simulator (MQTT) and Unreal Engine data
// NO MOCK DATA GENERATION - only routes real data

// Handle Unreal Engine data (comes as buffer from factory/data/* topics)
if (msg.payload && msg.topic && msg.topic.startsWith('factory/data/') && !msg.topic.includes('tick')) {
    try {
        node.warn('BRAIN: Raw Unreal buffer: ' + msg.payload.toString());
        // Fix malformed JSON from Unreal Engine:
        // 1. Remove thousand separator commas in numbers (e.g., 2,151 -> 2151)
        // 2. Fix missing commas after numbers (e.g., 5. "In -> 5, "In)
        let cleaned = msg.payload.toString()
            .replace(/(\d+),(\d{3})/g, '$1$2')  // Remove thousand separators
            .replace(/(\d+)\.\s+"/g, '$1, "');  // Fix missing commas after decimals
        node.warn('BRAIN: Cleaned Unreal JSON: ' + cleaned);
        let data = JSON.parse(cleaned);
        let dev = msg.topic.split('/').pop();
        node.warn('BRAIN: ✅ Unreal data - Device=' + dev + ' RPM=' + (data.rpm || 'N/A') + ' PosX=' + (data.posX || 'N/A') + ' PosY=' + (data.posY || 'N/A'));

        // Forward to collector formatter
        return [null, { topic: 'collector/ingest', payload: { device: dev, data: data, type: 'UNREAL' } }];
    } catch(e) { 
        node.warn('BRAIN: ❌ Unreal parse error: ' + e.message); 
        return null;
    }
}

// Handle Python Simulator sensor data (comes from plc/* topics)
if (msg.payload && msg.topic && msg.topic.startsWith('plc/') && msg.payload.type === 'sensor') {
    try {
        let sensorData = msg.payload;
        let sensorId = sensorData.device_id;
        let sensorValue = sensorData.data && sensorData.data.signal_config ? sensorData.data.signal_config.value : 0;
        let sensorName = sensorData.data && sensorData.data.name ? sensorData.data.name : sensorId;
        let unit = sensorData.data && sensorData.data.signal_config ? sensorData.data.signal_config.unit : '';

        node.warn('BRAIN: ✅ Simulator data - ' + sensorName + '=' + sensorValue.toFixed(2) + ' ' + unit);

        // Forward simulator data to collector
        return [null, { topic: 'collector/ingest', payload: sensorData }];
    } catch(e) {
        node.warn('BRAIN: ❌ Simulator parse error: ' + e.message);
        return null;
    }
}

// Handle tick for Modbus (but don't generate mock data)
if (msg.topic === 'tick') {
    // Just update Modbus registers with last known values from flow context
    let c1 = flow.get('c1_rpm') || 0;
    let c2 = flow.get('c2_rpm') || 0;
    let px = flow.get('placer_x') || 0;
    let py = flow.get('placer_y') || 0;
    let c1_on = flow.get('c1_on') || false;
    let c2_on = flow.get('c2_on') || false;
    let p1_ready = flow.get('p1_ready') || false;

    let mask = 0;
    if (c1_on) mask |= (1 << 0); 
    if (c2_on) mask |= (1 << 1); 
    if (p1_ready) mask |= (1 << 3);

    let buf = Buffer.alloc(10);
    buf.writeUInt16BE(c1, 0); 
    buf.writeUInt16BE(c2, 2); 
    buf.writeUInt16BE(px, 4); 
    buf.writeUInt16BE(py, 6); 
    buf.writeUInt16BE(mask, 8);

    return [{ payload: { value: buf, register: 'holding', address: 1, disableMsgOutput: 1 } }, null];
}

return null;

// Format data for collector/ingest topic
// Handles both Unreal Engine devices and Python Simulator sensors

// Handle UNREAL device data from THE BRAIN
if (msg.payload.type === 'UNREAL' && msg.payload.device && msg.payload.data) {
    let timestamp = Date.now() / 1000;
    let device = msg.payload.device;
    let data = msg.payload.data;
    node.warn('FORMAT: ✅ Unreal Device=' + device + ' Data=' + JSON.stringify(data));

    let metadata = {
        tenant: 'accenture',
        factory: 'test_factory',
        processed_at: new Date().toISOString(),
        category: 'UNREAL',
        priority: 'medium'
    };

    // Create device message with proper structure for collector
    let deviceMsg = {
        device_id: device.toLowerCase(),
        type: 'UNREAL',
        timestamp: timestamp,
        data: data,
        metadata: metadata
    };

    node.warn('FORMAT: ➡️ Sending to collector/ingest - ' + JSON.stringify(deviceMsg));
    return { topic: 'collector/ingest', payload: deviceMsg };
}

// Handle Python Simulator sensor data
if (msg.payload && msg.payload.type === 'sensor') {
    node.warn('FORMAT: ✅ Simulator Sensor=' + msg.payload.device_id);
    // Simulator data is already in the correct format, just forward it
    return { topic: 'collector/ingest', payload: msg.payload };
}

// Unknown message type - log warning
node.warn('FORMAT: ⚠️ Unknown message type: ' + JSON.stringify(msg.payload));
return null;
